/* Bundled chart copies prevent missing-image icons when the assets directory is omitted. */
const CHART_IMAGE_DATA={"transistor.jpg":"data:image/webp;base64,","logic.svg":"data:image/svg+xml;base64,","microprocessor.jpg":"data:image/webp;base64,","lovelace.jpg":"data:image/webp;base64,","programming.png":"data:image/webp;base64,","ml.svg":"data:image/svg+xml;base64,","history.jpg":"data:image/webp;base64,","writer.png":"data:image/webp;base64,","presentation.png":"data:image/webp;base64,","spreadsheet.png":"data:image/webp;base64,","pascaline.jpg":"data:image/webp;base64,","abacus.jpg":"data:image/webp;base64,","computer.jpg":"data:image/webp;base64,","network.jpg":"data:image/webp;base64,","difference-engine.jpg":"data:image/webp;base64,","web.jpg":"data:image/webp;base64,","topic-chart-01.webp":"data:image/webp;base64,","topic-chart-02.webp":"data:image/webp;base64,","topic-chart-03.webp":"data:image/webp;base64,","topic-chart-04.webp":"data:image/webp;base64,","topic-chart-05.webp":"data:image/webp;base64,","topic-chart-06.webp":"data:image/webp;base64,","topic-chart-07.webp":"data:image/webp;base64,","topic-chart-08.webp":"data:image/webp;base64,","topic-chart-09.webp":"data:image/webp;base64,","topic-chart-10.webp":"data:image/webp;base64,"};
/* Local, accessible image-and-text charts for every teaching note. */
const CHART_OBJECT_URLS={};
function chartImageUrl(name){const data=CHART_IMAGE_DATA[name];if(!data)return "assets/"+name;if(CHART_OBJECT_URLS[name])return CHART_OBJECT_URLS[name];if(typeof URL=== "undefined"||!URL.createObjectURL||typeof atob!=="function")return data;try{const comma=data.indexOf(","),mime=data.slice(5,data.indexOf(";")),raw=atob(data.slice(comma+1)),bytes=new Uint8Array(raw.length);for(let n=0;n<raw.length;n++)bytes[n]=raw.charCodeAt(n);return CHART_OBJECT_URLS[name]=URL.createObjectURL(new Blob([bytes],{type:mime}))}catch{return data}}
const CHART_HISTORY=[
 {year:'Early counting',image:'abacus.jpg',file:'Schoty abacus.jpg',caption:'A later Russian abacus illustrates physical counting tools; it is not an ancient artifact.'},
 {year:'c. 1642',image:'pascaline.jpg',file:'Pascaline calculator.jpg',caption:'The Pascaline illustrates an early mechanical calculator.',source:'https://www.computerhistory.org/revolution/calculators/1/45'},
 {year:'1847–1849',image:'difference-engine.jpg',file:'Difference Engine No. 2.jpg',caption:'Modern reconstruction of Babbage’s Difference Engine No. 2 design, with Ada Lovelace’s portrait below.',source:'https://www.computerhistory.org/babbage/engines/' ,extra:{image:'lovelace.jpg',file:'Ada Lovelace portrait.jpg',caption:'Portrait of Ada Lovelace, whose writing explored what programmable machines might do.'}},
 {year:'1946',image:'history.jpg',file:'Classic shot of the ENIAC.jpg',caption:'ENIAC illustrates vacuum-tube era computers.',source:'https://www.computerhistory.org/timeline/1946/'},
 {year:'1947',image:'transistor.jpg',file:'1st-Transistor.jpg',caption:'The first point-contact transistor at Bell Labs. Photo: Wikimedia Commons, CC BY-SA 3.0.',source:'https://www.computerhistory.org/siliconengine/invention-of-the-point-contact-transistor/'},
 {year:'Integrated circuits',image:'microprocessor.jpg',file:'C4004 (Intel).jpg',caption:'The 1971 Intel 4004 is a later integrated circuit example, not the first integrated circuit.'},
 {year:'1971',image:'microprocessor.jpg',file:'C4004 (Intel).jpg',caption:'Intel 4004, an early commercial single-chip microprocessor.',source:'https://www.computerhistory.org/siliconengine/microprocessor-integrates-cpu-function-onto-a-single-chip/'},
 {year:'Personal computers',image:'computer.jpg',file:'Xbox-Motherboard-Rev1.jpg',caption:'A modern motherboard used as a comparison with earlier personal computers.'},
 {year:'1969 → 1989',image:'network.jpg',file:'1969 ARPANET BBN IMP.jpg',caption:'ARPANET equipment illustrates an Internet precursor; the Web was proposed in 1989.',source:'https://home.cern/science/computing/the-birth-of-the-web/short-history-web/'},
 {year:'Review timeline',image:'history.jpg',file:'Classic shot of the ENIAC.jpg',caption:'Use this historical image to compare machine size, components and purpose across eras.'}
];
let chartScale=1;
function chartEscape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function chartMedia(item){const link='https://commons.wikimedia.org/wiki/File:'+encodeURIComponent(item.file);return `<figure class="chart-figure"><div class="chart-image"><img src="${chartImageUrl(item.image)}" alt="${chartEscape(item.caption)}" loading="lazy"></div><figcaption>${chartEscape(item.caption)} <a href="${link}" target="_blank" rel="noopener noreferrer">Image source and license ↗</a></figcaption></figure>`}
function chartSetZoom(delta){chartScale=Math.min(2.2,Math.max(.8,Math.round((chartScale+delta)*10)/10));chartApplyZoom()}
function chartResetZoom(){chartScale=1;chartApplyZoom()}
function chartApplyZoom(){const root=document.getElementById('conceptCharts');if(!root)return;root.style.setProperty('--chart-zoom',String(chartScale));const out=document.getElementById('chartZoomValue');if(out)out.textContent=Math.round(chartScale*100)+'%';root.querySelector('[data-zoom-out]')?.toggleAttribute('disabled',chartScale<=.8);root.querySelector('[data-zoom-in]')?.toggleAttribute('disabled',chartScale>=2.2)}
function chartDiagram(title,explanation,topic,index){
  const sentences=String(explanation).split(/(?<=[.!?])\s+|;\s*/).filter(Boolean);
  const fragments=sentences.length>=3?sentences:explanation.split(/,\s+|;\s+|\s+and\s+/i).filter(Boolean);
  const stages=fragments.length>=3?fragments.slice(0,3):[title,fragments[0]||explanation,fragments[1]||'Result'];
  const words=stages.map((part,n)=>{let label=part.replace(/^(The |A |An |It |They )/i,'').replace(/[.!?]$/,'').trim();if(label.length>66)label=label.slice(0,63).replace(/\s+\S*$/,'')+'…';return label||['Start','Transform','Result'][n]});
  const iconSets=['⌨','⚙','▣','◈','◎','▥','✦','⌁','▤','◉'];
  const colors=['#67d7ff','#fbbf24','#7ee3ad','#c4a8ff','#ff9dab'];
  const color=colors[(topic+index)%colors.length];
  const panels=words.map((word,n)=>`<g transform="translate(${24+n*254},76)"><rect width="230" height="164" rx="18" fill="#17334c" stroke="${color}" stroke-width="2"/><circle class="pulse" cx="115" cy="46" r="30" fill="#254f69"/><text x="115" y="58" text-anchor="middle" fill="${color}" font-size="31" font-family="sans-serif">${iconSets[(topic*3+index+n)%iconSets.length]}</text><foreignObject x="12" y="86" width="206" height="68"><div xmlns="http://www.w3.org/1999/xhtml" style="color:#fff;font:600 15px/1.25 system-ui,sans-serif;text-align:center;overflow-wrap:anywhere">${chartEscape(word)}</div></foreignObject></g>`).join('');
  const path='M 253 158 L 277 158 M 507 158 L 531 158';
  return `<div class="chart-illustration" role="img" aria-label="${chartEscape(title)}: ${words.map(chartEscape).join(' → ')}"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 790 260" aria-hidden="true"><text x="24" y="35" fill="#e7f5ff" font-size="23" font-weight="700" font-family="sans-serif">${chartEscape(title.slice(0,58))}</text><path d="${path}" stroke="${color}" stroke-width="4" stroke-linecap="round"/><circle class="signal" r="6" fill="#fff" style="offset-path:path('M 253 158 L 531 158')"/>${panels}</svg></div>`
}
let chartStep=0,chartTopic=-1,chartPlaying=true,chartTimer=null;
function chartShowStep(step){const lesson=L[i];if(!lesson)return;chartStep=(step+lesson.sections.length)%lesson.sections.length;const [title,explanation]=lesson.sections[chartStep];const historical=i===1?CHART_HISTORY[chartStep]:null;const visual=document.getElementById('chartStage');if(!visual)return;visual.innerHTML=`<div class="chart-stage-heading"><strong>Step ${chartStep+1} of ${lesson.sections.length}: ${chartEscape(title)}</strong><span class="chart-stage-counter">${chartPlaying?'● Playing':'Ⅱ Paused'}</span></div>${historical?`<div class="chart-history-photo">${chartMedia(historical)}</div>`:''}${chartDiagram(title,explanation,i,chartStep)}<div class="chart-step-detail"><h4>${chartEscape(title)}</h4><p>${chartEscape(explanation)}</p></div><button type="button" class="chart-explore" onclick="openNoteIn3D(${i},${chartStep})">🧊 Explore this concept in 3D</button>`;const select=document.getElementById('chartStepSelect');if(select)select.value=String(chartStep);document.getElementById('chartProgress').style.width=((chartStep+1)/lesson.sections.length*100)+'%';chartApplyZoom()}
function chartAdvance(delta){chartShowStep(chartStep+delta)}
function chartTogglePlay(){chartPlaying=!chartPlaying;const btn=document.getElementById('chartPlay');if(btn){btn.textContent=chartPlaying?'Ⅱ Pause':'▶ Play';btn.setAttribute('aria-label',chartPlaying?'Pause chart animation':'Play chart animation')}chartShowStep(chartStep)}
function chartRender(){const box=document.getElementById('chartList');if(!box)return;const topic=i,lesson=L[topic];if(chartTopic!==topic){chartTopic=topic;chartStep=0}box.innerHTML=`<div class="chart-topic-heading"><h3>${chartEscape(lesson.title)}</h3><p>${chartEscape(lesson.overview)}</p></div><div class="chart-step-controls"><button type="button" onclick="chartAdvance(-1)" aria-label="Previous concept">← Previous</button><label for="chartStepSelect">Concept</label><select id="chartStepSelect" onchange="chartShowStep(Number(this.value))">${lesson.sections.map(([title],j)=>`<option value="${j}">${j+1}. ${chartEscape(title)}</option>`).join('')}</select><button type="button" onclick="chartAdvance(1)" aria-label="Next concept">Next →</button><button id="chartPlay" type="button" onclick="chartTogglePlay()" aria-label="${chartPlaying?'Pause':'Play'} chart animation">${chartPlaying?'Ⅱ Pause':'▶ Play'}</button></div><div class="chart-progress-track" aria-hidden="true"><div id="chartProgress"></div></div><div id="chartStage" aria-live="polite"></div>`;chartShowStep(chartStep);if(chartTimer)clearInterval(chartTimer);chartTimer=setInterval(()=>{if(chartPlaying&&document.getElementById('conceptCharts'))chartAdvance(1)},6500)}
function chartInit(){const notes=document.querySelector('.notes-under-lab');if(!notes)return;const sec=document.createElement('section');sec.className='card concept-chart';sec.id='conceptCharts';sec.innerHTML='<h2>🖼 Images + Text Charts</h2><p>Watch the topic chart step through each concept, or choose a step yourself. Use zoom to make the chart readable across the classroom.</p><div class="chart-tools" role="group" aria-label="Chart zoom"><button type="button" data-zoom-out onclick="chartSetZoom(-.2)" aria-label="Zoom chart out">− Zoom out</button><output id="chartZoomValue" aria-live="polite">100%</output><button type="button" data-zoom-in onclick="chartSetZoom(.2)" aria-label="Zoom chart in">+ Zoom in</button><button type="button" onclick="chartResetZoom()">Reset 100%</button></div><div id="chartList"></div>';notes.insertAdjacentElement('afterend',sec);chartRender()}
chartInit();

function topicCardRender(){const host=document.querySelector('.visuals');if(!host)return;let hero=host.querySelector('.topic-illustrated-card');if(!hero){hero=document.createElement('figure');hero.className='topic-illustrated-card';const images=host.querySelector('.images');if(images){const more=document.createElement('details');more.className='topic-extra-diagrams';const summary=document.createElement('summary');summary.textContent='View additional topic diagrams';images.parentNode.insertBefore(more,images);more.append(summary,images);more.parentNode.insertBefore(hero,more)}else host.appendChild(hero)}const lesson=L[i];hero.innerHTML=`<img src="${chartImageUrl(`topic-chart-${String(i+1).padStart(2,'0')}.webp`)}" alt="Illustrated overview for ${chartEscape(lesson.title)}" loading="eager"><figcaption>${chartEscape(lesson.title)} · illustrated overview</figcaption>`}
topicCardRender();
